<?php require_once __DIR__.'/../config.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);$status=$_POST['status']??'Pending';$allowed=['Pending','Confirmed','Processing','Dispatched','Delivered','Cancelled'];if(in_array($status,$allowed,true)){db()->prepare('UPDATE orders SET status=?,tracking_number=?,tracking_url=? WHERE id=?')->execute([$status,trim($_POST['tracking_number']??''),trim($_POST['tracking_url']??''),$id]);flash('Order updated.');}header('Location: /powervault/admin/orders.php');exit;}$orders=db()->query('SELECT * FROM orders ORDER BY id DESC')->fetchAll();$pageTitle='Orders';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container-fluid admin-layout"><aside class="admin-sidebar"><div class="eyebrow">CONTROL CENTER</div><a href="/powervault/admin/">▦ Dashboard</a><a href="/powervault/admin/products.php">◇ Products</a><a href="/powervault/admin/inventory.php">▤ Inventory</a><a class="active" href="/powervault/admin/orders.php">⇄ Orders</a><a href="/powervault/admin/profit-loss.php">⌁ Profit & Loss</a><a href="/powervault/admin/settings.php">⚙ Settings</a><a href="/powervault/logout.php">↪ Logout</a></aside><div class="admin-content"><div class="eyebrow">ORDER MANAGEMENT</div><h1>Customer <span class="gradient-text">Orders</span></h1><?=get_flash()?><div class="dashboard-panel mt-4"><div class="table-responsive"><table class="table pv-table"><thead><tr><th>Order / Customer</th><th>Payment</th><th>Total</th><th>Update status / TCS</th></tr></thead><tbody><?php foreach($orders as $o): ?><tr><td><b><?=e($o['order_number'])?></b><small class="d-block"><?=e($o['customer_name'])?> · <?=e($o['phone'])?></small><small class="d-block muted"><?=e($o['address'])?>, <?=e($o['city'])?></small></td><td><?=e($o['payment_method'])?><small class="d-block muted"><?=e($o['payment_status'])?></small></td><td><?=money($o['total'])?></td><td><form method="post" class="order-edit"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$o['id']?>"><select name="status" class="form-select mb-2"><?php foreach(['Pending','Confirmed','Processing','Dispatched','Delivered','Cancelled'] as $st): ?><option <?=$o['status']===$st?'selected':''?>><?=$st?></option><?php endforeach; ?></select><input class="form-control mb-2" name="tracking_number" placeholder="TCS tracking number" value="<?=e($o['tracking_number']??'')?>"><input class="form-control mb-2" name="tracking_url" placeholder="Tracking URL" value="<?=e($o['tracking_url']??'')?>"><button class="btn btn-neon btn-sm">Save</button></form></td></tr><?php endforeach; ?><?php if(!$orders): ?><tr><td colspan="4">No orders received yet.</td></tr><?php endif; ?></tbody></table></div></div></div></div></section><?php require __DIR__.'/../includes/footer.php';?>
